using Vector=std::array<double,3>;
using Matrix=std::array<Vector,3>;
struct Pose { Matrix matrix{};Vector rate{}; };
static double dot(const Vector&a,const Vector&b){double v=0;for(int i=0;i<3;++i)v+=a[i]*b[i];return v;}
static Vector add(Vector a,const Vector&b){for(int i=0;i<3;++i)a[i]+=b[i];return a;}
static Vector scale(Vector a,double v){for(auto&x:a)x*=v;return a;}
static QJsonArray json(const Vector&v){QJsonArray r;for(double x:v)r.append(x);return r;}
static QJsonArray json(const Matrix&m){QJsonArray r;for(auto&v:m)r.append(json(v));return r;}
static double tdb(double epoch){return TimeSystemConverter::Instance()->Convert(epoch,TimeSystemConverter::A1MJD,TimeSystemConverter::TDBMJD,2430000.0);}
static Pose expected(const QJsonObject&matrix,const QJsonObject&spec,double elapsed){
 Pose p;p.matrix={Vector{1,0,0},Vector{0,1,0},Vector{0,0,1}};const auto kind=spec["oracle"].toString();const double pi=std::acos(-1.),rad=pi/180.;
 if(kind=="ecliptic"){const double e=84381.448/3600.*rad;p.matrix={Vector{1,0,0},Vector{0,std::cos(e),std::sin(e)},Vector{0,-std::sin(e),std::cos(e)}};}
 if(kind=="body"){
  const auto body=matrix["body_orientation"].toObject();const auto rates=spec["pole_rates_degrees_per_century"].toArray();const double epoch=matrix["epoch_a1_mjd"].toDouble()+elapsed/86400.,days=tdb(epoch)-tdb(body["reference_epoch_a1_mjd"].toDouble());
  const double a=(body["pole_ra_degrees"].toDouble()+rates[0].toDouble()*days/36525.)*rad,d=(body["pole_dec_degrees"].toDouble()+rates[1].toDouble()*days/36525.)*rad,w=(body["prime_meridian_degrees"].toDouble()+body["rotation_rate_degrees_day"].toDouble()*days)*rad;
  const double ad=rates[0].toDouble()*rad/(36525.*86400.),dd=rates[1].toDouble()*rad/(36525.*86400.),wd=body["rotation_rate_degrees_day"].toDouble()*rad/86400.;const double ca=std::cos(a),sa=std::sin(a),cd=std::cos(d),sd=std::sin(d),cw=std::cos(w),sw=std::sin(w);
  const Vector n{-sa,ca,0},m{-sd*ca,-sd*sa,cd},z{cd*ca,cd*sa,sd},nd{-ca*ad,-sa*ad,0},md{sd*sa*ad-cd*ca*dd,-sd*ca*ad-cd*sa*dd,-sd*dd},zd{-cd*sa*ad-sd*ca*dd,cd*ca*ad-sd*sa*dd,cd*dd};
  p.matrix={add(scale(n,cw),scale(m,sw)),add(scale(n,-sw),scale(m,cw)),z};
  const Matrix derivative{add(add(scale(n,-sw*wd),scale(nd,cw)),add(scale(m,cw*wd),scale(md,sw))),add(add(scale(n,-cw*wd),scale(nd,-sw)),add(scale(m,-sw*wd),scale(md,cw))),zd};
  p.rate={-dot(derivative[2],p.matrix[1])/rad,-dot(derivative[0],p.matrix[2])/rad,-dot(derivative[1],p.matrix[0])/rad};
 }
 if(kind=="radial"||kind=="velocity"){
  const double radius=matrix["radius_km"].toDouble(),omega=std::sqrt(matrix["mu_km3_s2"].toDouble()/(radius*radius*radius)),angle=omega*elapsed,c=std::cos(angle),s=std::sin(angle);
  if(kind=="radial"){p.matrix={Vector{c,s,0},Vector{-s,c,0},Vector{0,0,1}};p.rate={0,0,omega/rad};}
  else{p.matrix={Vector{-s,c,0},Vector{0,0,1},Vector{c,s,0}};p.rate={0,omega/rad,0};}
 }
 return p;
}
